public class InnerDataAutomationProjectImageStandardExtractionFactory(Action<Humidifier.Bedrock.DataAutomationProjectTypes.ImageStandardExtraction> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.DataAutomationProjectTypes.ImageStandardExtraction>
{

    internal InnerDataAutomationProjectImageExtractionCategoryFactory CategoryFactory { get; set; }

    internal InnerDataAutomationProjectImageBoundingBoxFactory BoundingBoxFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.ImageStandardExtraction Create()
    {
        var imageStandardExtractionResult = CreateImageStandardExtraction();
        factoryAction?.Invoke(imageStandardExtractionResult);

        return imageStandardExtractionResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.ImageStandardExtraction CreateImageStandardExtraction()
    {
        var imageStandardExtractionResult = new Humidifier.Bedrock.DataAutomationProjectTypes.ImageStandardExtraction();

        return imageStandardExtractionResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.ImageStandardExtraction result)
    {
        base.CreateChildren(result);

        result.Category ??= CategoryFactory?.Build();
        result.BoundingBox ??= BoundingBoxFactory?.Build();
    }

} // End Of Class

